  unsigned salt = rand();
  static char const format[] = "/tmp/error-%#X.log"
  char fname[16 + sizeof format];
  snprintf(fname, sizeof fname, format, salt);
  errlog = fopen(fname, "w");
  if (errlog) {
    setvbuf(errlog, 0, _IOLBF, 0);   // Enables line buffering
  }
